from curva import CurvaError, RateLimitError, InvalidRequestError, ModelError

try:
    d = client.decide(state, QUESTIONS, project="support")
except InvalidRequestError as e:
    log.error("bad question: %s", e.message)    # don't retry: fix the question
    raise
except RateLimitError as e:
    requeue(item, delay=e.retry_after)
except ModelError as e:
    if e.type == "model_unavailable":
        alert("model id or access is wrong: %s" % e.message)
    requeue(item, delay=60)
except CurvaError as e:
    log.error("curva %s %s: %s", e.status, e.type, e.message)
    raise
